"""Deployment: two configured copies, atomic, validated, never half done."""
from pathlib import Path

from woweconomy.pricing import deploy
from woweconomy.pricing.config import PricingConfig


def lua(generated_at: int = 1, price: int = 100) -> str:
    """A minimal dataset the validator accepts, distinct per argument."""
    return (
        "-- Generated by the DfA pricing engine.  Do not edit by hand.\n"
        f"-- schema 2, engine 2.0.0, generated {generated_at}\n"
        "\n"
        "DFA_ESTIMATE = {\n"
        "\tversion = 2,\n"
        '\tengineVersion = "2.0.0",\n'
        f"\tgeneratedAt = {generated_at},\n"
        "\titemCount = 1,\n"
        "\trealmCount = 1,\n"
        "\tappearanceCount = 0,\n"
        "\ttotalObservations = 1,\n"
        "\tpriceCount = 1,\n"
        "\tindexedRealms = 1,\n"
        "\tprices = {\n"
        f"\t\t[1]={price},\n"
        "\t},\n"
        "}\n"
    )


def write(path: Path, text: str) -> None:
    """Exact bytes: the deployment copies bytes, so the fixture must too."""
    path.write_text(text, encoding="utf-8", newline="\n")


def make(tmp_path, *, install_addon: bool = True, text: str | None = None):
    dataset = tmp_path / "project" / "DFA_Estimate" / "Data" / deploy.DATA_FILE
    dataset.parent.mkdir(parents=True)
    write(dataset, text if text is not None else lua())

    addons = tmp_path / "AddOns"
    if install_addon:
        addon_dir = addons / deploy.PACKAGE
        (addon_dir / "Data").mkdir(parents=True)
        write(addon_dir / "DFA_Estimate.toc", "## Interface: 110000\n")
        write(addon_dir / "DFA_Estimate.lua", "local Addon = {}\n")

    config = PricingConfig(dataset_path=dataset, addons_dir=addons)
    installed = addons / deploy.PACKAGE / "Data" / deploy.DATA_FILE
    return config, dataset, installed


def test_both_copies_are_discovered_from_configuration(tmp_path):
    config, dataset, installed = make(tmp_path)

    targets = deploy.discover_targets(config)

    assert [(target.name, target.path) for target in targets] == [
        ("project", dataset), ("addon", installed)]
    elsewhere = deploy.discover_targets(config, addons_dir=tmp_path / "Elsewhere")
    assert elsewhere[1].path == (tmp_path / "Elsewhere" / deploy.PACKAGE
                                 / "Data" / deploy.DATA_FILE)


def test_a_changed_dataset_reaches_both_copies_and_leaves_the_addon_alone(tmp_path):
    config, dataset, installed = make(tmp_path)
    deploy.deploy(config)
    addon_dir = installed.parent.parent
    toc, main = addon_dir / "DFA_Estimate.toc", addon_dir / "DFA_Estimate.lua"
    toc_before, main_before = toc.read_bytes(), main.read_bytes()

    write(dataset, lua(2))
    result = deploy.deploy(config)

    assert result.ok is True
    assert installed.read_bytes() == dataset.read_bytes()
    # a deployment is a data change, not an addon rewrite
    assert toc.read_bytes() == toc_before
    assert main.read_bytes() == main_before
    assert {path.name for path in installed.parent.iterdir()} == {
        deploy.DATA_FILE, deploy.DATA_FILE + deploy.BACKUP_SUFFIX}


def test_an_unchanged_dataset_is_not_rewritten(tmp_path):
    config, _, installed = make(tmp_path)
    assert deploy.deploy(config).ok is True
    before = (installed.stat().st_mtime_ns, installed.stat().st_size)

    result = deploy.deploy(config)

    assert result.ok is True
    assert {target.status for target in result.targets} == {"unchanged"}
    assert (installed.stat().st_mtime_ns, installed.stat().st_size) == before


def test_a_dataset_that_does_not_validate_is_never_shipped(tmp_path):
    config, dataset, installed = make(tmp_path)
    assert deploy.deploy(config).ok is True
    good = installed.read_bytes()

    write(dataset, "this is not a dataset\n")
    result = deploy.deploy(config)

    assert result.ok is False
    assert result.problems
    assert installed.read_bytes() == good
    assert {target.status for target in result.targets} == {"skipped"}


def test_the_replaced_copy_is_kept_as_a_valid_backup(tmp_path):
    config, dataset, installed = make(tmp_path)
    first = dataset.read_bytes()
    deploy.deploy(config)

    write(dataset, lua(2))
    result = deploy.deploy(config)

    backup = installed.with_name(installed.name + deploy.BACKUP_SUFFIX)
    assert backup.read_bytes() == first
    addon = next(target for target in result.targets if target.name == "addon")
    assert addon.backup == str(backup)


def test_a_broken_copy_never_overwrites_the_last_good_backup(tmp_path):
    config, dataset, installed = make(tmp_path)
    deploy.deploy(config)
    write(dataset, lua(2))
    deploy.deploy(config)
    backup = installed.with_name(installed.name + deploy.BACKUP_SUFFIX)
    good_backup = backup.read_bytes()

    # the game copy is now garbage; the next deploy must not save it over
    write(installed, "truncated\n")
    write(dataset, lua(3))
    deploy.deploy(config)

    assert backup.read_bytes() == good_backup


def test_a_locked_destination_is_retried(tmp_path):
    config, dataset, installed = make(tmp_path)
    calls = {"n": 0}

    def flaky(source, target):
        calls["n"] += 1
        if calls["n"] <= 2:
            raise PermissionError("the game is holding it")
        deploy.os.replace(source, target)

    result = deploy.deploy(config, replace=flaky, sleep=lambda _: None)

    assert result.ok is True
    addon = next(target for target in result.targets if target.name == "addon")
    assert addon.status == "written"
    assert addon.attempts == 3
    assert installed.read_bytes() == dataset.read_bytes()


def test_a_destination_that_never_accepts_a_write_fails_the_deployment(tmp_path):
    config, dataset, installed = make(tmp_path)

    def locked(source, target):
        raise PermissionError("the game is holding it")

    result = deploy.deploy(config, replace=locked, sleep=lambda _: None, attempts=2)

    assert result.ok is False
    addon = next(target for target in result.targets if target.name == "addon")
    assert addon.status == "failed"
    assert "the game is holding it" in addon.error
    assert not installed.exists()


def test_a_failed_write_leaves_the_previous_copy_intact(tmp_path):
    config, dataset, installed = make(tmp_path)
    deploy.deploy(config)
    before = installed.read_bytes()

    def locked(source, target):
        raise PermissionError("the game is holding it")

    write(dataset, lua(3))
    result = deploy.deploy(config, replace=locked, sleep=lambda _: None, attempts=1)

    assert result.ok is False
    assert installed.read_bytes() == before


def test_a_missing_addon_directory_is_reported_not_created(tmp_path):
    config, dataset, installed = make(tmp_path, install_addon=False)

    result = deploy.deploy(config)

    assert result.ok is False
    addon = next(target for target in result.targets if target.name == "addon")
    assert addon.status == "missing"
    assert "does not exist" in addon.error
    # the project copy is still the canonical artefact and is not written
    # again (it already holds these bytes); the addon was never created
    project = next(target for target in result.targets if target.name == "project")
    assert project.status == "unchanged"
    assert not (config.addons_dir / deploy.PACKAGE).exists()


def test_a_missing_canonical_dataset_fails_without_touching_the_addon(tmp_path):
    config, dataset, installed = make(tmp_path)
    dataset.unlink()

    result = deploy.deploy(config)

    assert result.ok is False
    assert "missing" in result.problems[0]
    assert not installed.exists()


def test_a_new_export_during_the_copy_is_shipped_as_well(tmp_path):
    config, dataset, installed = make(tmp_path)
    newer = lua(99)
    seen = {"exported": False}

    def export_landed(source, target):
        deploy.os.replace(source, target)
        if not seen["exported"]:
            seen["exported"] = True
            write(dataset, newer)

    result = deploy.deploy(config, replace=export_landed, sleep=lambda _: None)

    assert result.ok is True
    assert result.passes == 2
    assert result.superseded is False
    assert installed.read_bytes() == newer.encode("utf-8")
    assert dataset.read_bytes() == newer.encode("utf-8")


def test_a_source_that_keeps_changing_is_reported_superseded(tmp_path):
    config, dataset, installed = make(tmp_path)
    counter = {"n": 0}

    def always_newer(source, target):
        deploy.os.replace(source, target)
        counter["n"] += 1
        write(dataset, lua(1_000 + counter["n"]))

    result = deploy.deploy(config, replace=always_newer, sleep=lambda _: None,
                           passes=3)

    assert result.superseded is True
    assert result.ok is False
    assert result.passes == 3


def test_verify_says_in_sync_only_when_both_copies_match(tmp_path):
    config, dataset, installed = make(tmp_path)
    deploy.deploy(config)

    assert deploy.verify(config)["in_sync"] is True

    write(installed, lua(7))
    report = deploy.verify(config)

    assert report["in_sync"] is False
    assert "the copies differ" in report["problems"]
    assert len(report["targets"]) == 2
    assert all(target["valid"] for target in report["targets"])
